fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0
    if (seconds >= 1.0) {
        val s = if (seconds == 1.0) "1" else String.format("%.1f", seconds).replace("\\.0+$", "".toRegex())
        return "${s}s"
    }
    val denominator = Math.round(1_000_000_000.0 / exposureTimeNs)
    return "1/${denominator}s"
}

