import sys

def remove_comments(content):
    state = 'NORMAL'  # can be NORMAL, IN_STRING, IN_SINGLE_LINE_COMMENT, IN_MULTI_LINE_COMMENT
    output = []
    i = 0
    n = len(content)
    while i < n:
        c = content[i]
        if state == 'NORMAL':
            if c == '"':
                state = 'IN_STRING'
                output.append(c)
            elif c == '/':
                if i+1 < n:
                    next_c = content[i+1]
                    if next_c == '/':
                        state = 'IN_SINGLE_LINE_COMMENT'
                        i += 1  # skip the next slash
                    elif next_c == '*':
                        state = 'IN_MULTI_LINE_COMMENT'
                        i += 1  # skip the next asterisk
                    else:
                        output.append(c)
                else:
                    output.append(c)
            else:
                output.append(c)
        elif state == 'IN_STRING':
            output.append(c)
            if c == '"':
                # Check if this quote is escaped: look back at the output (without the current quote) for consecutive backslashes
                j = len(output) - 2  # because we just added the current quote, so the one before is at index -2
                count = 0
                while j >= 0 and output[j] == '\\':
                    count += 1
                    j -= 1
                if count % 2 == 0:
                    state = 'NORMAL'
        elif state == 'IN_SINGLE_LINE_COMMENT':
            if c == '\n':
                state = 'NORMAL'
                output.append(c)  # keep the newline
            # else: skip the character
        elif state == 'IN_MULTI_LINE_COMMENT':
            if c == '*':
                if i+1 < n and content[i+1] == '/':
                    state = 'NORMAL'
                    i += 1  # skip the next slash
                # else: remain in comment, skip the character
            # else: skip the character
        i += 1
    return ''.join(output)

if __name__ == '__main__':
    with open(sys.argv[1], 'r') as f:
        content = f.read()
    result = remove_comments(content)
    with open(sys.argv[1], 'w') as f:
        f.write(result)
EOF

